reverse_cumsum_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reverse_cumsum_kernel(const float* __restrict__ a, 
                                        float* __restrict__ out, 
                                        int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum = 0.0f;
        for (int i = idx; i < total_elements; ++i) {
            sum += a[i];
        }
        out[idx] = sum;
    }
}

torch::Tensor reverse_cumsum_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    reverse_cumsum_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

